var s = [];
function p(t, u, f, b, j) {
    var style = { layout_flexGrow: f, layout_flexBasisPercent: b };
    if (j) style.layout_justifySelf = j;
    s.push({ title: t, url: u || '', style: style });
}
function getConfig() {
    try {
        var raw = source.getVariable();
        if (raw && raw !== '' && raw !== 'null' && raw !== 'undefined') return JSON.parse(raw);
    } catch (e) {}
    return {};
}
var config = getConfig();
var selectedGroup = config.exploreGroup || '排行榜';

s.push({ title: "☃关键词:书名/作者🔖", type: "text", style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.6 } });
