    {
        key: 'search_update_status',
        title: '📅 更新状态',
        options: { '不选': null, '完结': '1', '半年内完结': '2', '连载中': '3', '3日内更新': '4', '7日内更新': '5', '1月内更新': '6' }
    },
    {
        key: 'search_words',
        title: '📏 字数篇幅',
        options: { '不选': null, '10万字以内': '1', '30万字以内': '2', '50万字以内': '3', '30万字以上': '4', '50万字以上': '5', '100万字以上': '6', '200万字以上': '7', '300万字以上': '8', '500万字以上': '9' }
