    }
];

var showSearchFilter = config.search_filter_show !== false;
if (showSearchFilter) {
    filterConfig.forEach(function(item) {
        var currentValue = config[item.key];
        var chars = Object.keys(item.options);
        var defaultLabel = '不选';
        for (var i = 0; i < chars.length; i++) {
            if (item.options[chars[i]] === currentValue) {
                defaultLabel = chars[i];
                break;
            }
        }
        var mapStr = JSON.stringify(item.options);
        var action = "(function(){ var c={}; try{ c=JSON.parse(source.getVariable()||'{}'); }catch(e){} var raw=infoMap['" + item.title + "']||'不选'; var map=" + mapStr + "; var v=map[raw]; if(v===null||v===undefined||v===''){ delete c['" + item.key + "']; } else { c['" + item.key + "']=v; } source.setVariable(JSON.stringify(c)); })()";
        s.push({
            title: item.title,
            type: "select",
            chars: chars,
            default: defaultLabel,
            action: action,
            style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.4 }
        });
    });
}

s.push({ title: "🔑登录", type: "button", action: "java.open('login','http',null);saveKeys(infoMap)", style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.4, layout_alignSelf: "baseline" } });
